"use client"

import type { ReactNode } from "react"

import { AppShell } from "@/registry/templates/app-shell-01/app-shell"
import { HeaderStatus } from "@/registry/templates/app-shell-01/header-status"
import { navConfig } from "@/registry/templates/app-shell-01/nav-config"
import { services } from "@/registry/templates/app-shell-01/sample-data"

/**
 * 控制台布局：app/(app) 路由组下的所有页面都会套上这层壳。
 * 导航数据里的图标是函数，不能从服务端组件传给客户端组件，所以这个布局是客户端组件。
 * 把 brand、user、onSignOut 换成你自己的数据与登录逻辑。
 */
export default function AppLayout({ children }: { children: ReactNode }) {
  return (
    <AppShell
      nav={navConfig}
      brand={{ name: "Acme 控制台", tagline: "企业级监控与运维", href: "/dashboard" }}
      user={{ name: "管理员", email: "admin@example.com" }}
      onSignOut={() => {
        // TODO: 调用你的认证服务退出登录，然后跳转到 /login
      }}
      headerActions={<HeaderStatus services={services} />}
    >
      {children}
    </AppShell>
  )
}

import type { Metadata } from "next"

import { DashboardOverview } from "@/registry/templates/app-shell-01/dashboard-overview"

export const metadata: Metadata = {
  title: "概览",
}

/** 控制台首页：概览仪表盘。按同样的方式在 app/(app)/ 下添加更多页面，它们会自动套上侧栏与顶栏。 */
export default function DashboardPage() {
  return <DashboardOverview />
}

"use client"

import * as React from "react"
import { usePathname } from "next/navigation"

import {
  Sheet,
  SheetContent,
  SheetDescription,
  SheetHeader,
  SheetTitle,
} from "@/components/ui/sheet"
import { TooltipProvider } from "@/components/ui/tooltip"
import { cn } from "@/lib/utils"
import { useControllableState } from "@/registry/hooks/use-controllable-state"

import { AppHeader, type AppShellBrand } from "./app-header"
import {
  DEFAULT_STORAGE_KEY,
  resolveLabels,
  type AppShellLabels,
} from "./config"
import type { NavLinkBehavior } from "./nav-link"
import { resolveNav, type NavConfig } from "./nav-types"
import { PrimaryNav } from "./primary-nav"
import { useStoredFlag } from "./use-stored-flag"
import type { AppShellUser } from "./user-menu"
import { WorkspaceMobileNav, WorkspaceSidebar } from "./workspace-sidebar"

type AppShellProps = Omit<React.ComponentProps<"div">, "children"> & {
  /** 导航数据：一级导航 + 二级（工作区）侧栏，见 nav-config.ts */
  nav: NavConfig
  brand?: AppShellBrand
  /** 顶栏右侧的额外操作区，例如「AI 助手」按钮、服务状态 */
  headerActions?: React.ReactNode
  /** 主区域右侧的侧栏插槽（如 AI 助手面板）：与 main 并排，高度占满顶栏以下区域 */
  aside?: React.ReactNode
  user?: AppShellUser
  /** 额外的用户菜单项（DropdownMenuItem），放在「退出登录」之前 */
  userMenu?: React.ReactNode
  onSignOut?: () => void
  /** 当前地址，用于高亮导航；不传则取 usePathname() */
  activeHref?: string
  /** 传入后拦截导航链接的默认跳转并回调，适合预览 / 单页场景；接入路由时不要传 */
  onNavigate?: (payload: { href: string }) => void
  /** 侧栏是否折叠（受控）；不传则内部维护并记住在 localStorage */
  collapsed?: boolean
  /** 非受控时的初始折叠状态（无本地记录时生效） */
  defaultCollapsed?: boolean
  onCollapsedChange?: (collapsed: boolean) => void
  /** 非受控时记住折叠状态的 localStorage 键 */
  storageKey?: string
  /** 是否显示亮暗模式切换（依赖 next-themes），默认 true */
  themeToggle?: boolean
  /** 覆盖默认文案，见 config.ts 的 DEFAULT_LABELS */
  labels?: Partial<AppShellLabels>
  children: React.ReactNode
}

const defaultBrand: AppShellBrand = { name: "控制台" }

/**
 * 企业控制台布局：固定顶栏 + 可折叠一级导航 + 可选二级工作区侧栏 + 独立滚动的主区域 + 右侧 aside 插槽。
 * 窄屏（< 768px）一级导航变为左侧 Sheet 抽屉，二级导航变为顶栏下方的横向标签条。
 */
function AppShell({
  className,
  nav,
  brand = defaultBrand,
  headerActions,
  aside,
  user,
  userMenu,
  onSignOut,
  activeHref,
  onNavigate,
  collapsed: collapsedProp,
  defaultCollapsed = false,
  onCollapsedChange,
  storageKey = DEFAULT_STORAGE_KEY,
  themeToggle = true,
  labels,
  children,
  ...props
}: AppShellProps) {
  const text = resolveLabels(labels)
  const pathname = usePathname()
  const currentHref = activeHref ?? pathname
  const active = React.useMemo(
    () => resolveNav(nav, currentHref),
    [nav, currentHref]
  )

  // 非受控时折叠状态来自 localStorage（水合安全）；受控时完全由外部决定
  const [stored, setStored] = useStoredFlag(storageKey, defaultCollapsed)
  const [collapsed, setCollapsed] = useControllableState({
    prop: collapsedProp ?? stored,
    defaultProp: defaultCollapsed,
    onChange: (next) => {
      if (collapsedProp === undefined) setStored(next)
      onCollapsedChange?.(next)
    },
  })
  const [mobileOpen, setMobileOpen] = React.useState(false)

  const mainRef = React.useRef<HTMLElement>(null)
  React.useEffect(() => {
    mainRef.current?.scrollTo({ top: 0, left: 0 })
  }, [currentHref])

  const navigation = React.useMemo<NavLinkBehavior>(
    () => ({
      intercept: Boolean(onNavigate),
      onNavigate: (payload) => {
        setMobileOpen(false)
        onNavigate?.(payload)
      },
    }),
    [onNavigate]
  )

  const group = active?.module

  return (
    <TooltipProvider>
      <Sheet open={mobileOpen} onOpenChange={setMobileOpen}>
        <div
          data-slot="app-shell"
          data-collapsed={collapsed ? "" : undefined}
          data-has-aside={aside ? "" : undefined}
          data-has-workspace={group ? "" : undefined}
          className={cn(
            "flex h-svh flex-col overflow-hidden bg-muted/35 text-foreground",
            className
          )}
          {...props}
        >
          <a
            href="#main-content"
            className="sr-only focus:not-sr-only focus:fixed focus:top-4 focus:left-4 focus:z-[100] focus:rounded-md focus:bg-background focus:px-4 focus:py-2 focus:text-sm focus:font-medium focus:shadow-lg focus:ring-3 focus:ring-ring/50 focus:outline-none"
          >
            {text.skipToContent}
          </a>
          <AppHeader
            brand={brand}
            collapsed={collapsed}
            onToggleCollapsed={() => setCollapsed(!collapsed)}
            trail={active?.trail ?? []}
            actions={headerActions}
            themeToggle={themeToggle}
            user={user}
            userMenu={userMenu}
            onSignOut={onSignOut}
            navigation={navigation}
            labels={labels}
          />
          {group ? (
            <WorkspaceMobileNav
              module={group}
              activeId={active?.item.id}
              navigation={navigation}
              labels={labels}
            />
          ) : null}
          <div className="flex min-h-0 flex-1">
            <aside
              data-slot="app-shell-sidebar"
              data-collapsed={collapsed ? "" : undefined}
              className={cn(
                "hidden shrink-0 border-r border-sidebar-border bg-sidebar transition-[width] duration-200 motion-reduce:transition-none md:flex",
                collapsed ? "w-[60px]" : "w-[200px]"
              )}
            >
              <PrimaryNav
                config={nav}
                active={active}
                collapsed={collapsed}
                navigation={navigation}
                labels={labels}
              />
            </aside>
            {group ? (
              <WorkspaceSidebar
                module={group}
                activeId={active?.item.id}
                navigation={navigation}
                labels={labels}
              />
            ) : null}
            <main
              data-slot="app-shell-main"
              id="main-content"
              ref={mainRef}
              tabIndex={-1}
              aria-label={text.mainContent}
              className="min-h-0 min-w-0 flex-1 overflow-y-auto bg-background outline-none"
            >
              {children}
            </main>
            {aside}
          </div>
          <SheetContent
            side="left"
            className="gap-0 p-0 data-[side=left]:w-[280px] data-[side=left]:sm:max-w-[280px]"
          >
            <SheetHeader className="border-b border-border px-4 py-3">
              <SheetTitle className="text-sm">{text.mainNavigation}</SheetTitle>
              <SheetDescription className="sr-only">
                {text.mainNavigationDescription}
              </SheetDescription>
            </SheetHeader>
            <div className="flex min-h-0 flex-1 bg-sidebar">
              <PrimaryNav
                config={nav}
                active={active}
                navigation={navigation}
                labels={labels}
              />
            </div>
          </SheetContent>
        </div>
      </Sheet>
    </TooltipProvider>
  )
}

export { AppShell }
export type { AppShellBrand, AppShellProps, AppShellUser }

"use client"

import * as React from "react"
import { PanelLeftIcon } from "lucide-react"

import {
  Breadcrumb,
  BreadcrumbItem,
  BreadcrumbList,
  BreadcrumbPage,
  BreadcrumbSeparator,
} from "@/components/ui/breadcrumb"
import { Button } from "@/components/ui/button"
import { SheetTrigger } from "@/components/ui/sheet"
import { cn } from "@/lib/utils"

import { formatLabel, resolveLabels, type AppShellLabels } from "./config"
import { NavLink, type NavLinkBehavior } from "./nav-link"
import { ThemeToggle } from "./theme-toggle"
import { UserMenu, type AppShellUser } from "./user-menu"

type AppShellBrand = {
  name: string
  /** Logo 节点，建议 32×32 的 SVG / 图片；不传则用名称首字生成方块 */
  logo?: React.ReactNode
  /** 名称下方的一行说明，仅在侧栏展开的桌面端显示 */
  tagline?: string
  /** 点击品牌区跳转的地址，默认 "/" */
  href?: string
}

type AppHeaderProps = Omit<React.ComponentProps<"header">, "children"> & {
  brand: AppShellBrand
  collapsed: boolean
  onToggleCollapsed: () => void
  /** 面包屑：分组 → 模块 → 页面 */
  trail: string[]
  actions?: React.ReactNode
  themeToggle: boolean
  user?: AppShellUser
  userMenu?: React.ReactNode
  onSignOut?: () => void
  navigation?: NavLinkBehavior
  labels?: Partial<AppShellLabels>
}

/** 固定顶栏：左侧品牌区（宽度与一级导航对齐）+ 折叠按钮 + 面包屑 + 右侧操作区。 */
function AppHeader({
  className,
  brand,
  collapsed,
  onToggleCollapsed,
  trail,
  actions,
  themeToggle,
  user,
  userMenu,
  onSignOut,
  navigation,
  labels,
  ...props
}: AppHeaderProps) {
  const text = resolveLabels(labels)
  const toggleLabel = collapsed ? text.expandSidebar : text.collapseSidebar
  return (
    <header
      data-slot="app-shell-header"
      data-collapsed={collapsed ? "" : undefined}
      className={cn(
        "relative z-30 shrink-0 border-b border-sidebar-border bg-background",
        className
      )}
      {...props}
    >
      <div className="flex h-14 items-center">
        <div
          className={cn(
            "h-full shrink-0 border-r border-sidebar-border bg-sidebar px-3 transition-[width] duration-200 motion-reduce:transition-none sm:px-4",
            collapsed ? "w-[60px]" : "w-[200px] max-md:w-[60px]"
          )}
        >
          <NavLink
            href={brand.href ?? "/"}
            navigation={navigation}
            aria-label={formatLabel(text.brandHome, brand.name)}
            className={cn(
              "flex h-full min-w-0 items-center rounded-md outline-none focus-visible:ring-3 focus-visible:ring-ring/50",
              collapsed ? "justify-center" : "gap-2.5 max-md:justify-center"
            )}
          >
            <span className="flex size-8 shrink-0 items-center justify-center overflow-hidden rounded-lg">
              {brand.logo ?? (
                <span
                  aria-hidden="true"
                  className="flex size-full items-center justify-center bg-primary text-sm font-semibold text-primary-foreground"
                >
                  {brand.name.trim().slice(0, 1).toUpperCase()}
                </span>
              )}
            </span>
            {collapsed ? null : (
              <span className="hidden min-w-0 leading-tight md:block">
                <span className="block truncate text-sm font-semibold">
                  {brand.name}
                </span>
                {brand.tagline ? (
                  <span className="block truncate text-[11px] text-muted-foreground">
                    {brand.tagline}
                  </span>
                ) : null}
              </span>
            )}
          </NavLink>
        </div>

        <div className="flex min-w-0 flex-1 items-center gap-1.5 px-3 sm:px-4">
          <SheetTrigger
            render={
              <Button
                variant="ghost"
                size="icon"
                className="-ml-1 md:hidden"
                aria-label={text.openNavigation}
              />
            }
          >
            <PanelLeftIcon />
          </SheetTrigger>
          <Button
            variant="ghost"
            size="icon"
            className="-ml-1 hidden md:inline-flex"
            onClick={onToggleCollapsed}
            aria-label={toggleLabel}
            aria-expanded={!collapsed}
            title={toggleLabel}
          >
            <PanelLeftIcon />
          </Button>

          {trail.length > 0 ? (
            <Breadcrumb aria-label={text.breadcrumb} className="min-w-0">
              <BreadcrumbList className="flex-nowrap gap-1 overflow-hidden">
                {trail.map((label, index) => {
                  const last = index === trail.length - 1
                  return last ? (
                    <BreadcrumbItem
                      key={`${label}-${index}`}
                      className="min-w-0"
                    >
                      <BreadcrumbPage className="truncate font-semibold">
                        {label}
                      </BreadcrumbPage>
                    </BreadcrumbItem>
                  ) : (
                    <BreadcrumbItem
                      key={`${label}-${index}`}
                      className="hidden shrink-0 lg:inline-flex"
                    >
                      {label}
                      <BreadcrumbSeparator />
                    </BreadcrumbItem>
                  )
                })}
              </BreadcrumbList>
            </Breadcrumb>
          ) : null}

          <div className="ml-auto flex shrink-0 items-center gap-1 sm:gap-1.5">
            {actions}
            {themeToggle ? <ThemeToggle labels={labels} /> : null}
            {user ? (
              <UserMenu user={user} onSignOut={onSignOut} labels={labels}>
                {userMenu}
              </UserMenu>
            ) : null}
          </div>
        </div>
      </div>
    </header>
  )
}

export { AppHeader }
export type { AppHeaderProps, AppShellBrand }

"use client"

import * as React from "react"
import { ChevronRightIcon } from "lucide-react"

import {
  Tooltip,
  TooltipContent,
  TooltipTrigger,
} from "@/components/ui/tooltip"
import { cn } from "@/lib/utils"

import { resolveLabels, type AppShellLabels } from "./config"
import { NavLink, type NavLinkBehavior } from "./nav-link"
import {
  isModule,
  moduleHref,
  type NavConfig,
  type NavEntry,
  type NavSection,
  type ResolvedNav,
} from "./nav-types"

type PrimaryNavProps = Omit<React.ComponentProps<"nav">, "children"> & {
  config: NavConfig
  /** 当前页面对应的导航位置，由 resolveNav 得到 */
  active?: ResolvedNav
  /** 图标栏模式：只显示图标，名称放到 Tooltip 与读屏文本里 */
  collapsed?: boolean
  navigation?: NavLinkBehavior
  labels?: Partial<AppShellLabels>
}

/** 一级导航：分组标题 + 条目；模块条目指向其第一个子项，选中时左侧出现二级侧栏。 */
function PrimaryNav({
  className,
  config,
  active,
  collapsed = false,
  navigation,
  labels,
  ...props
}: PrimaryNavProps) {
  const text = resolveLabels(labels)

  function renderEntry(entry: NavEntry) {
    const isGroup = isModule(entry)
    const selected = isGroup
      ? active?.module?.id === entry.id
      : active?.item.id === entry.id
    const Icon = entry.icon
    const badge = isGroup ? undefined : entry.badge
    const link = (
      <NavLink
        data-slot="app-shell-nav-item"
        data-active={selected ? "" : undefined}
        href={isGroup ? moduleHref(entry) : entry.href}
        navigation={navigation}
        aria-current={selected ? (isGroup ? "true" : "page") : undefined}
        aria-label={collapsed ? entry.label : undefined}
        className={cn(
          "relative flex h-10 w-full min-w-0 items-center rounded-md text-sm transition-colors outline-none focus-visible:ring-3 focus-visible:ring-ring/50 motion-reduce:transition-none",
          collapsed ? "justify-center px-2" : "gap-3 px-3",
          selected
            ? "bg-primary/10 font-medium text-sidebar-foreground shadow-[inset_3px_0_0_var(--primary)]"
            : "text-sidebar-foreground/70 hover:bg-primary/5 hover:text-sidebar-foreground"
        )}
      >
        <Icon className="size-4 shrink-0" aria-hidden="true" />
        {collapsed ? (
          <>
            <span className="sr-only">{entry.label}</span>
            {badge !== undefined ? (
              <span
                aria-hidden="true"
                className="absolute top-2 right-2 size-1.5 rounded-full bg-primary"
              />
            ) : null}
          </>
        ) : (
          <>
            <span className="min-w-0 flex-1 truncate">{entry.label}</span>
            {badge !== undefined ? (
              <span className="rounded-full bg-primary/10 px-1.5 text-[11px] leading-5 font-medium text-primary tabular-nums">
                {badge}
              </span>
            ) : null}
            {isGroup ? (
              <ChevronRightIcon
                className="size-3 shrink-0 opacity-40"
                aria-hidden="true"
              />
            ) : null}
          </>
        )}
      </NavLink>
    )
    return (
      <li key={entry.id}>
        {collapsed ? (
          <Tooltip>
            <TooltipTrigger render={link} />
            <TooltipContent side="right">{entry.label}</TooltipContent>
          </Tooltip>
        ) : (
          link
        )}
      </li>
    )
  }

  function renderSection(section: NavSection) {
    return (
      <section key={section.id} aria-label={section.label}>
        <h2
          className={cn(
            "flex h-8 items-center px-3 text-[11px] font-medium text-sidebar-foreground/50",
            collapsed && "sr-only"
          )}
        >
          {section.label}
        </h2>
        <ul className="flex flex-col gap-1">
          {section.entries.map(renderEntry)}
        </ul>
      </section>
    )
  }

  return (
    <nav
      data-slot="app-shell-primary-nav"
      data-collapsed={collapsed ? "" : undefined}
      aria-label={text.mainNavigation}
      className={cn("flex h-full min-h-0 flex-1 flex-col", className)}
      {...props}
    >
      <div className="flex min-h-0 flex-1 flex-col gap-6 overflow-y-auto px-2 py-4">
        {config.sections.map(renderSection)}
      </div>
      {config.footer ? (
        <div className="shrink-0 border-t border-sidebar-border px-2 py-3">
          {renderSection(config.footer)}
        </div>
      ) : null}
    </nav>
  )
}

export { PrimaryNav }
export type { PrimaryNavProps }

"use client"

import * as React from "react"

import { cn } from "@/lib/utils"

import { formatLabel, resolveLabels, type AppShellLabels } from "./config"
import { NavLink, type NavLinkBehavior } from "./nav-link"
import type { NavModule } from "./nav-types"

type WorkspaceNavProps = Omit<React.ComponentProps<"nav">, "children"> & {
  module: NavModule
  /** 当前选中的子项 id */
  activeId?: string
  navigation?: NavLinkBehavior
  labels?: Partial<AppShellLabels>
}

function WorkspaceNav({
  className,
  module: group,
  activeId,
  navigation,
  labels,
  mobile = false,
  ...props
}: WorkspaceNavProps & { mobile?: boolean }) {
  const text = resolveLabels(labels)
  const navRef = React.useRef<HTMLElement>(null)

  // 移动端是横向滚动条：让当前项保持在可视区域中间
  React.useEffect(() => {
    const nav = navRef.current
    if (!mobile || !nav) return
    function reveal() {
      const current = nav!.querySelector<HTMLElement>('a[aria-current="page"]')
      if (current && nav!.clientWidth) {
        nav!.scrollLeft =
          current.offsetLeft -
          nav!.offsetLeft -
          (nav!.clientWidth - current.clientWidth) / 2
      }
    }
    reveal()
    const observer = new ResizeObserver(reveal)
    observer.observe(nav)
    return () => observer.disconnect()
  }, [activeId, mobile])

  return (
    <nav
      data-slot="app-shell-workspace-nav"
      data-mobile={mobile ? "" : undefined}
      ref={navRef}
      aria-label={formatLabel(text.workspaceNavigation, group.label)}
      className={cn(
        "flex",
        mobile
          ? "h-10 shrink-0 items-center gap-1.5 overflow-x-auto overflow-y-hidden border-b border-border bg-muted/20 px-3 [scrollbar-width:none] md:hidden [&::-webkit-scrollbar]:hidden"
          : "min-h-0 flex-1 flex-col gap-1.5 overflow-y-auto px-3 py-4",
        className
      )}
      {...props}
    >
      {group.items.map((item) => {
        const active = item.id === activeId
        const Icon = item.icon
        return (
          <NavLink
            key={item.id}
            data-slot="app-shell-workspace-item"
            data-active={active ? "" : undefined}
            href={item.href}
            navigation={navigation}
            aria-current={active ? "page" : undefined}
            className={cn(
              "flex min-w-0 shrink-0 items-center rounded-md transition-colors outline-none focus-visible:ring-3 focus-visible:ring-ring/50 motion-reduce:transition-none",
              mobile
                ? "h-7 gap-1.5 px-2.5 text-xs"
                : "min-h-14 gap-2.5 px-3 py-2.5 text-sm",
              active
                ? "bg-primary/10 font-medium text-foreground shadow-[inset_3px_0_0_var(--primary)]"
                : "text-muted-foreground hover:bg-muted hover:text-foreground"
            )}
          >
            <Icon
              aria-hidden="true"
              className={mobile ? "size-3.5 shrink-0" : "size-4 shrink-0"}
            />
            <span className="min-w-0 flex-1 text-left">
              <span className="block truncate">{item.label}</span>
              {!mobile && item.description ? (
                <span className="mt-0.5 block truncate text-[11px] font-normal text-muted-foreground">
                  {item.description}
                </span>
              ) : null}
            </span>
            {!mobile && item.badge !== undefined ? (
              <span className="rounded-full bg-primary/10 px-1.5 text-[11px] leading-5 font-medium text-primary tabular-nums">
                {item.badge}
              </span>
            ) : null}
          </NavLink>
        )
      })}
    </nav>
  )
}

/** 窄屏下二级导航：Header 下方的横向滚动标签条。 */
function WorkspaceMobileNav(props: WorkspaceNavProps) {
  return <WorkspaceNav {...props} mobile />
}

/** 二级（工作区）侧栏：模块标题 + 子项列表，宽屏显示在一级导航右侧。 */
function WorkspaceSidebar({
  className,
  ...props
}: WorkspaceNavProps) {
  const { module: group, labels } = props
  const text = resolveLabels(labels)
  const GroupIcon = group.icon
  return (
    <aside
